from moler.cmd.unix.genericunix import GenericUnixCommand


class UtfLabUpdates(GenericUnixCommand):
    """utf_lab-updates start commnad class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        utf_lab-updates command.

        :param connection: Moler connection to device, terminal when command is executed.
        :param prompt: prompt (on system where command runs).
        :param newline_chars: Characters to split lines - list.
        :param runner: Runner to run command.
        """
        super(UtfLabUpdates, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.current_ret['CURRENT_VERSION'] = ''
        self.current_ret['LATEST_VERSION'] = ''
        self.current_ret['INSTALLER'] = ''
        self.current_ret['UPDATE_AVAILABLE'] = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "utf_lab-updates"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Parse output lines.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            if "Currently installed version" in line:
                self.current_ret['CURRENT_VERSION'] = line.split(':')[1].lstrip()
            elif "Latest released version" in line:
                self.current_ret['LATEST_VERSION'] = line.split(':')[1].lstrip()
            elif "has been downloaded to" in line:
                self.current_ret['INSTALLER'] = line.split(':')[1].lstrip()
            elif "Please update your UTF Lab." in line:
                self.current_ret['UPDATE_AVAILABLE'] = True
        return super(UtfLabUpdates, self).on_new_line(line, is_full_line)


